import * as THREE from "three";
import { loadHead, parseHead, type HeadBase } from "./headMesh";

// Everything the app loads from public/models: the base head, and a shape for each horn style and the
// orc's tusk (generated by tools/export_horns.py).

export const SHAPE_NAMES = ["ram", "goat", "bull", "demon", "antelope", "stubby", "tusk"] as const;
export type ShapeName = (typeof SHAPE_NAMES)[number];

export interface ShapeAsset {
  positions: Float32Array;
  t: Float32Array; // 0 at the base of the shape, 1 at the tip
  indices: Uint32Array;
}

export interface Assets {
  head: HeadBase;
  shapes: Record<ShapeName, ShapeAsset>;
}

export function parseShape(buffer: ArrayBuffer): ShapeAsset {
  const header = new Uint32Array(buffer, 0, 2);
  const vertices = header[0];
  const triangles = header[1];
  return {
    positions: new Float32Array(buffer.slice(8, 8 + vertices * 12)),
    t: new Float32Array(buffer.slice(8 + vertices * 12, 8 + vertices * 16)),
    indices: new Uint32Array(buffer.slice(8 + vertices * 16, 8 + vertices * 16 + triangles * 12)),
  };
}

export function parseAssets(head: ArrayBuffer, shapes: Record<ShapeName, ArrayBuffer>, feminine?: ArrayBuffer): Assets {
  const parsed = {} as Record<ShapeName, ShapeAsset>;
  for (const name of SHAPE_NAMES) parsed[name] = parseShape(shapes[name]);
  return { head: parseHead(head, feminine), shapes: parsed };
}

export async function loadAssets(): Promise<Assets> {
  const [head, ...shapes] = await Promise.all([
    loadHead(),
    ...SHAPE_NAMES.map(async (name) => {
      const response = await fetch(`${import.meta.env.BASE_URL}models/horns/${name}.bin`);
      if (!response.ok) throw new Error(`Could not load the ${name} model (${response.status})`);
      return parseShape(await response.arrayBuffer());
    }),
  ]);
  const byName = {} as Record<ShapeName, ShapeAsset>;
  SHAPE_NAMES.forEach((name, i) => (byName[name] = shapes[i]));
  return { head, shapes: byName };
}

const smooth = (t: number) => {
  const c = Math.min(1, Math.max(0, t));
  return c * c * (3 - 2 * c);
};

// A shape as renderable geometry, coloured from its base to its tip: a darker, stained root, a paler
// shaft, and a tip that darkens (horns) or whitens (tusks).
export function shapeGeometry(asset: ShapeAsset, root: THREE.Color, shaft: THREE.Color, tip: THREE.Color): THREE.BufferGeometry {
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute("position", new THREE.BufferAttribute(asset.positions, 3));
  geometry.setIndex(new THREE.BufferAttribute(asset.indices, 1));
  geometry.computeVertexNormals();
  const colors = new Float32Array(asset.t.length * 3);
  const c = new THREE.Color();
  for (let i = 0; i < asset.t.length; i++) {
    const t = asset.t[i];
    c.copy(root).lerp(shaft, smooth(t / 0.3)).lerp(tip, smooth((t - 0.7) / 0.3));
    colors[i * 3] = c.r;
    colors[i * 3 + 1] = c.g;
    colors[i * 3 + 2] = c.b;
  }
  geometry.setAttribute("color", new THREE.BufferAttribute(colors, 3));
  return geometry;
}
